            Q('cu1', L('A che cosa servono le istruzioni personalizzate?', 'What are custom instructions for?'), [L('Dire come vuoi le risposte in ogni chat', 'Saying how you want answers in every chat'), L('Cambiare il modello', 'Changing the model'), L('Pagare meno', 'Paying less'), L('Cancellare la cronologia', 'Deleting history')], 0, L('Tono, formato, chi sei.', 'Tone, format, who you are.')),
            Q('cu2', L('Puoi controllare la memoria di ChatGPT?', 'Can you control ChatGPT’s memory?'), [L('Sì: vederla, correggerla o spegnerla', 'Yes: view, correct or turn it off'), L('No, è nascosta', 'No, it is hidden'), L('Solo pagando', 'Only by paying'), L('Solo via API', 'Only via API')], 0, L('Dalle impostazioni.', 'From the settings.')),
            Q('cu3', L('Quando conviene un progetto?', 'When is a project useful?'), [L('Quando lavori a lungo su un tema con file e chat', 'When you work long on one topic with files and chats'), L('Per una domanda veloce', 'For a quick question'), L('Per generare un’immagine', 'To generate an image'), L('Mai', 'Never')], 0, L('Il contesto resta insieme.', 'The context stays together.')),
        ], task('text', L('Scrivi istruzioni personalizzate di due righe: una che dica il tuo ruolo (inizia con `Sono`) e una sul formato (inizia con `Rispondi`).', 'Write two-line custom instructions: one stating your role (start with `Sono`) and one about the format (start with `Rispondi`).'), '', [re('^Sono\s+\S.{5,}', L('Dici il tuo ruolo', 'You state your role')), re('^Rispondi\s+\S.{5,}', L('Chiedi un formato', 'You ask for a format'))], '', "Sono un insegnante di informatica alle superiori.\nRispondi in italiano, con esempi brevi ed elenchi puntati."), [
            dMatch(pMatch(), [[L('Istruzioni personalizzate', 'Custom instructions'), L('Valgono in ogni chat', 'Apply to every chat')], [L('Memoria', 'Memory'), L('Fatti ricordati tra chat', 'Facts remembered across chats')], [L('Progetto', 'Project'), L('Chat e file su un tema', 'Chats and files on a topic')], ['GPT', L('Assistente condivisibile', 'Shareable assistant')]], L('Personalizzare ChatGPT.', 'Personalising ChatGPT.')),
            dFlash(pFlash(), [[L('La memoria si può spegnere', 'Memory can be turned off'), true], [L('Le istruzioni valgono solo per un messaggio', 'Instructions apply to one message only'), false], [L('Un GPT può avere file propri', 'A GPT can have its own files'), true], [L('La memoria non si può mai correggere', 'Memory can never be corrected'), false]], L('Su misura.', 'Made to measure.')),
        ]),
